<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Safety reports | Edu Connect</title>
<style>body{font:16px/1.6 system-ui;color:#17243a;background:#f5f7fa;margin:0}main{max-width:900px;margin:auto;padding:32px 20px}article{background:white;border:1px solid #dce2ed;border-radius:12px;padding:24px;margin:20px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}label{display:block;margin:12px 0}textarea,input,select,button{font:inherit;padding:10px;max-width:100%;box-sizing:border-box}textarea{width:100%}button{background:#213e92;color:white;border:0;border-radius:7px;cursor:pointer}a{color:#213e92}.muted{color:#5d6e88}#status{white-space:pre-wrap}</style></head>
<body><main><a href="/admin">Back to administration</a><h1>Safety reports</h1><p>Platform administrators review reports here. Investigate the identified content and user, record your action, and follow up with the reporter. School notices, journal posts and documents can be managed in the school administration portal.</p><button id="refresh">Refresh reports</button><p id="status" role="status"></p><section id="reports"></section></main>
<script>
const status=document.getElementById('status'),list=document.getElementById('reports');
async function api(path,method='GET',data){const token=localStorage.getItem('admin_token');if(!token)throw Error('Sign into the administration portal first.');const r=await fetch('/api'+path,{method,headers:{Authorization:'Bearer '+token,Accept:'application/json','Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});const body=await r.json();if(!r.ok)throw Error(body.message||'Access denied. Platform administrator access is required.');return body;}
function element(tag,text){const e=document.createElement(tag);if(text)e.textContent=text;return e;}
async function load(){status.textContent='Loading reports…';try{const data=await api('/moderation/reports');list.replaceChildren();for(const report of data.reports){const card=element('article');card.append(element('h2','Report #'+report.id+' · '+report.review_status),element('p','Reporter account: '+(report.user_id??'Deleted')+' · '+report.created_at),element('pre',report.message));const form=element('form');const state=element('select');for(const name of ['pending','reviewing','resolved']){const o=element('option',name);o.value=name;state.append(o);}state.value=report.review_status;const notes=element('textarea');notes.rows=4;notes.required=true;notes.minLength=5;notes.maxLength=5000;notes.value=report.review_notes||'';notes.placeholder='Investigation, action taken and follow-up';const id=element('input');id.type='number';id.min=1;id.placeholder='Optional message ID to remove';const warning=element('p','Only enter a message ID after verifying it relates to this report. Removal hides it from both participants.');const save=element('button','Save review');form.append(element('label','Review status'),state,element('label','Review notes'),notes,element('label','Remove an objectionable direct message (optional)'),id,warning,save);form.onsubmit=async(event)=>{event.preventDefault();if(id.value&&!confirm('Remove message '+id.value+' from both participants?'))return;save.disabled=true;try{await api('/moderation/reports/'+report.id,'PUT',{review_status:state.value,review_notes:notes.value,...(id.value?{hide_message_id:Number(id.value)}:{})});await load();}catch(e){status.textContent=e.message;save.disabled=false;}};card.append(form);list.append(card);}status.textContent=data.reports.length?'Loaded latest '+data.reports.length+' reports.':'No safety reports.';}catch(e){status.textContent=e.message;}}
document.getElementById('refresh').onclick=load;load();
</script></body></html>
